#!/usr/bin/env bash
#===============================================================================
#
#   Arctic Fox Anonymity v1.0.0  -  SINGLE-FILE SELF-EXTRACTING INSTALLER
#
#   Agar zip file download na ho paye to bas YE EK file download karo:
#
#       1.  Is file ko download karo          (arcticfox_installer.sh)
#       2.  Terminal me chalao:
#               bash arcticfox_installer.sh
#
#   Ye script khud saari files extract karegi (arcticfox, install.sh,
#   uninstall.sh, README.md, logo.png, LICENSE, completions) aur phir
#   system-wide install bhi kar degi (sudo ke sath).
#
#   FOR LEGAL / ETHICAL USE ONLY.
#
#===============================================================================
set -e
C_R='\033[1;31m'; C_G='\033[1;32m'; C_Y='\033[1;33m'; C_C='\033[1;36m'; C_0='\033[0m'

echo ""
echo -e "${C_C}     _          _         _   ___          _${C_0}"
echo -e "${C_C}    /_\\  _ __ __| |__ _| |_ / __|__ _ _ __| |_ ___ _ _${C_0}"
echo -e "${C_C}   / _ \\|\\ V // _\` / _\`|  _| (__/ _\` | '_ \\  _/ -_) '_|${C_0}"
echo -e "${C_C}  /_/ \\_\\\\_/\\ \\__,_\\__,_|\\__|\\___\\__,_| .__/\\__\\___|_|${C_0}"
echo -e "${C_C}          |___/            |_|       |_${C_0}"
echo ""
echo -e "${C_G}[+]${C_0} Arctic Fox Anonymity - self-extracting installer v1.0.2"
echo ""

#--- 1. Extract embedded files ---------------------------------------------------
echo -e "${C_Y}[*]${C_0} Extracting files..."
if awk '/^#==PAYLOAD==/{flag=1;next}/^#==END==/{flag=0}flag' "$0" | base64 -d | tar xzf -; then
    echo -e "${C_G}[+]${C_0} Extracted: Arctic-Fox-Anonymity/ (all files)"
else
    echo -e "${C_R}[-]${C_0} Extraction failed! File corrupted during download?"
    echo -e "    Try downloading this file again."
    exit 1
fi

#--- 2. Verify checksums ----------------------------------------------------------
if command -v sha256sum >/dev/null 2>&1; then
    ( cd Arctic-Fox-Anonymity && sha256sum -c checksums.txt >/dev/null 2>&1 ) \
        && echo -e "${C_G}[+]${C_0} Integrity check passed." \
        || echo -e "${C_Y}[!]${C_0} Integrity check skipped/failed (continuing anyway)."
fi

#--- 3. Run the installer ---------------------------------------------------------
echo ""
echo -e "${C_Y}[*]${C_0} Starting system-wide installation (tor + arcticfox command)..."
if [ "$(id -u)" -eq 0 ]; then
    bash Arctic-Fox-Anonymity/install.sh
elif command -v sudo >/dev/null 2>&1; then
    sudo bash Arctic-Fox-Anonymity/install.sh || {
        echo ""
        echo -e "${C_Y}[!]${C_0} Automatic install did not finish. Files are ready though!"
        echo -e "    Manual install:  cd Arctic-Fox-Anonymity && sudo bash install.sh"
        exit 0
    }
else
    echo -e "${C_Y}[!]${C_0} Files extracted to Arctic-Fox-Anonymity/"
    echo -e "    Run as root:  cd Arctic-Fox-Anonymity && bash install.sh"
fi

exit 0
